rows=[]
with open("results/ppo_countdown/metrics.jsonl") as f:
    for line in f:
        rows.append(json.loads(line))

def flatten(o, prefix=""):
    out={}
    if isinstance(o, dict):
        for k,v in o.items():
            out.update(flatten(v, prefix+"/"+k if prefix else k))
    else:
        out[prefix]=o
    return out

# union keys for train
print("=== ALL TRAIN KEYS ===")
keys=set()
train=[]
