    if r["step_key"]!="train/step":
        continue
    flat=flatten(r["data"])
    keys |= set(flat)
    train.append((r["step"], flat))
for k in sorted(keys):
    print(k)

print("\n=== train steps unique", sorted(set(s for s,_ in train)))
print("count per step", {s:sum(1 for ss,_ in train if ss==s) for s in sorted(set(s for s,_ in train))})

print("\n=== EVAL SERIES ===")
for r in rows:
    if r["step_key"]=="eval/step":
        d=flatten(r["data"])
        keys_show=["eval/countdown","eval/countdown/raw_reward_mean","eval/countdown/truncated_ratio","eval/countdown-truncated_ratio","eval/countdown/response_len/mean","eval/countdown/response_len/max","eval/countdown/response_len/min","eval/countdown/repetition_frac"]
        print(f"step {r['step']}: " + ", ".join(f"{k.split('/')[-1] if k.count('/')>2 else k}={d.get(k)}" for k in keys_show))

print("\n=== ROLLOUT SERIES (one per step, last occurrence) ===")
by=defaultdict(list)
for r in rows:
    if r["step_key"]=="rollout/step":
        by[r["step"]].append(flatten(r["data"]))
print("n events per step:", {s:len(v) for s,v in sorted(by.items())})
print(f"{'step':>4} {'rew':>8} {'trunc':>8} {'len_mean':>8} {'len_max':>8} {'len_p50':>8} {'rep':>8} {'time':>8} {'wv':>6}")
for s,vs in sorted(by.items()):
    # print all if they differ
    for i,d in enumerate(vs):
        print(f"{s:4d}.{i} {d.get('rollout/raw_reward_mean'):8.4f} {d.get('rollout/truncated_ratio'):8.4f} {d.get('rollout/response_len/mean'):8.1f} {d.get('rollout/response_len/max'):8.1f} {d.get('rollout/response_len/p50'):8.1f} {d.get('rollout/repetition_frac'):8.4f} {d.get('perf/rollout_time'):8.2f} {d.get('rollout/weight_version/mean')}")
