    def _post_process_rewards(self, samples: list[Sample] | list[list[Sample]]):
        if self.custom_reward_post_process_func is not None:
            return self.custom_reward_post_process_func(self.args, samples)

        raw_rewards = [sample.get_reward_value(self.args) for sample in samples]

        # DAPO Soft Overlong Punishment: add a length penalty to the reward that feeds advantage
        # computation, while keeping raw_rewards as the pure task reward for logging. The penalty is
        # only applied when the reward is a plain scalar (dict/multi-key rewards are left untouched).
780→        shaped_rewards = raw_rewards
        if getattr(self.args, "overlong_buffer_len", 0):
            if all(isinstance(r, (int, float)) for r in raw_rewards):
                shaped_rewards = [
                    r + compute_overlong_penalty(self.args, sample.response_length)
                    for r, sample in zip(raw_rewards, samples, strict=True)
                ]
            else:
                logger.warning(
                    "overlong_buffer_len is set but rewards are non-scalar; "
790→                    "skipping soft overlong punishment for this batch."
                )

        if (
            self.args.advantage_estimator in ["grpo", "gspo", "reinforce_plus_plus_baseline"]
            and self.args.rewards_normalization
        ):
            # group norm
            rewards = torch.tensor(shaped_rewards, dtype=torch.float)
            if rewards.shape[-1] == self.args.n_samples_per_prompt * self.args.rollout_batch_size:
800→                rewards = rewards.reshape(-1, self.args.n_samples_per_prompt)
            else:
                # when samples count are not equal in each group
                rewards = rewards.view(-1, rewards.shape[-1])
            mean = rewards.mean(dim=-1, keepdim=True)
            rewards = rewards - mean

            if self.args.advantage_estimator in ["grpo", "gspo"] and self.args.grpo_std_normalization:
                std = rewards.std(dim=-1, keepdim=True)
                rewards = rewards / (std + 1e-6)
810→
            return raw_rewards, rewards.flatten().tolist()

        return raw_rewards, shaped_rewards

    def _convert_samples_to_train_data(self, samples: list[Sample] | list[list[Sample]]):
        """
        Convert inference generated samples to training data.
        """
        if self.custom_convert_samples_to_train_data_func is not None:
820→            return self.custom_convert_samples_to_train_data_func(self.args, samples)

        raw_rewards, rewards = self._post_process_rewards(samples)

        assert len(raw_rewards) == len(samples)
        assert len(rewards) == len(samples)

        # --critic-exclude-overlong-penalty: ship a second per-sample reward without the soft
        # overlong punishment for the critic's regression target. The penalty is additive, so
        # subtracting it from the shaped reward is exact. Absent the flag this branch adds
830→        # nothing and the batch is unchanged.
        critic_rewards = None
        if getattr(self.args, "critic_exclude_overlong_penalty", False):
            if (
                self.custom_reward_post_process_func is None
                and getattr(self.args, "overlong_buffer_len", 0)
                and all(isinstance(r, (int, float)) for r in raw_rewards)
            ):
                critic_rewards = [
                    r - compute_overlong_penalty(self.args, sample.response_length)
840→                    for r, sample in zip(rewards, samples, strict=True)
                ]
            else:
                logger.warning(
                    "critic_exclude_overlong_penalty is set but no overlong penalty was applied "
                    "(custom reward post-process, non-scalar rewards, or overlong_buffer_len=0); "
                    "critic rewards fall back to the shaped rewards."
                )
                critic_rewards = list(rewards)

850→        train_data = {
            "tokens": [sample.tokens for sample in samples],
            "response_lengths": [sample.response_length for sample in samples],
            # some reward model, e.g. remote rm, may return multiple rewards,
            # we could use key to select the reward.
